// Spawns a Axe moby copying fields from another and placing it at a position.
void *spawn_axe_moby(char *src, char *pos) {
    char tmp[16];
    char *p = tmp;
    char *m;
    *(u128 *)tmp = *(u128 *)pos;
    m = (char *)CreateMoby(0x23A);
    if (m != 0) {
        ((struct Moby *)m)->update_dist = 0xFF;
        ((struct Moby *)m)->draw_dist = *(unsigned short *)(src + 0x32);
        ((struct Moby *)m)->visible = 1;
        *(int *)&((struct Moby *)m)->rot.x = 0;
        *(int *)&((struct Moby *)m)->rot.y = 0;
        ((struct Moby *)m)->rot.z = *(float *)(src + 0x48);
        ((struct Moby *)m)->spawn_frame = *(u64 *)(src + 0x38);
        qcopy(&((struct Moby *)m)->pos, p);
        moby_build_matrix(m);
    }
    return m;
}

